#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum FloatOutBoyParkingBrakeMode {
    Always,
    Idle,
    Never,
    Unknown(u8),
}

impl From<u8> for FloatOutBoyParkingBrakeMode {
    fn from(value: u8) -> Self {
        match value {
            0 => Self::Always,
            1 => Self::Idle,
            2 => Self::Never,
            value => Self::Unknown(value),
        }
    }
}

